recipe:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  inputs = import ./boot-preparation-baseline-inputs.nix {inherit pkgs;};
  test = minimal: import (root + "/tests/build/_bazel-cargo-oracle.nix") (inputs // {
    inherit pkgs;
    pname = "aos-bazel-boot-preparation-${if minimal then "minimal-" else ""}cargo-baseline";
    cargoFlags = pkgs.lib.optional minimal "--no-default-features";
  });
  production = minimal: pkgs.mkDerivation {
    pname = "aos-bazel-boot-preparation-${if minimal then "minimal-" else ""}production-cargo-baseline";
    version = "1";
    src = inputs.cargoSource;
    buildDeps = [pkgs.rust pkgs.sed] ++ inputs.nativeTools;
    runtimeDeps = inputs.nativeLibraries;
    sharedBuildCache = false;
    dontStrip = true;
    dontPatchELF = true;
    dontNukeRefs = true;
    phases = [{
      name = "compile";
      script = ''
        cp -R "$src" source
        chmod -R u+w source
        cd source
        export CARGO_HOME="$TMPDIR/cargo" CARGO_TARGET_DIR="$TMPDIR/target"
        mkdir -p "$CARGO_HOME" .cargo "$out"
        sed 's|@vendor@|${pkgs.aos.passthru.cargoDeps}|g' \
          ${pkgs.aos.passthru.cargoDeps}/.cargo/config.toml > .cargo/config.toml
        ${inputs.cargoSetup}
        cargo build --frozen --offline --manifest-path crates/Cargo.toml --lib --bins \
          -p aos-boot-runtime -p aos-configuration-image -p aos-platform-metadata \
          ${pkgs.lib.optionalString minimal "--no-default-features"} \
          --jobs "$NIX_BUILD_CORES" --message-format=json > "$out/cargo-messages.jsonl"
      '';
    }];
  };
in { baselines = [(test false) (production false) (test true) (production true)]; }

shared_inputs_recipe:
{pkgs}: let
  common = import ./registry-native-baseline-inputs.nix {inherit pkgs;};
in common // {
  packages = ["aos-boot-runtime" "aos-configuration-image" "aos-platform-metadata"];
  nativeTools = common.nativeTools ++ [pkgs.erofs-utils pkgs.util-linux pkgs.aos.packageRuntime];
  cargoSetup = common.cargoSetup + ''
    export AOS_MKFS_EROFS="${pkgs.erofs-utils}/bin/mkfs.erofs"
    export AOS_FSCK_EROFS="${pkgs.erofs-utils}/bin/fsck.erofs"
    export AOS_MOUNT="${pkgs.util-linux}/bin/mount"
    export AOS_UMOUNT="${pkgs.util-linux}/bin/umount"
    export AOS_PACKAGE_RUNTIME="${pkgs.aos.packageRuntime}/bin/aos-package-runtime"
  '';
}
